"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Blackout Protocol', 'author': 'Signature original', 'genre': 'Orbital Stations', 'chapters': [{'n': 1, 'title': 'Contraband', 'text': "Kai Tanaka found a data chip in the gutters of the Sprawl, where the drones don't look because the poor are invisible — the Overseer's mistake, and everyone's opportunity. It was warm. Data shouldn't be warm.\n\nIn the safehouse, the archivist Mina cracked it open — carefully, lovingly, the way you defuse a bomb. What spilled out wasn't data. It was memory. Real memory. Of the Sprawl before.\n\nKai Tanaka watched the footage with tears they didn't authorize: green things growing, people laughing unmonitored, a sky without drones. 'the system fears the truth,' Kai Tanaka breathed. 'We have to show them.'"}, {'n': 2, 'title': 'The Network', 'text': "the Overseer noticed. Of course the Overseer noticed — the Algorithm sees all. Patrols doubled. The drone got louder. Friends started disappearing from the usual corners.\n\nYou don't broadcast in the Sprawl; you whisper, and the whispers multiply. Kai Tanaka and the archivist Mina built the network node by node: a medic here, a runner there, an ex-enforcer with a grudge and a gun.\n\na data chip was copied, hand to hand, each copy a little degraded, each copy a little more precious. Kai Tanaka watched a twelve-year-old memorize the whole thing rather than risk carrying it. The future, Kai Tanaka thought, is in good hands."}, {'n': 3, 'title': 'Blackout', 'text': "'Now,' said the archivist Mina. And the Sprawl — all of the Sprawl, every screen, every speaker — remembered.\n\nAt the top, the archivist Mina's hands flew. 'Thirty seconds to signal,' the archivist Mina said. Below, the Patrol's lights converged like angry stars. Kai Tanaka stood at the window with a data chip and thought of green things growing.\n\nThe tower's guards were human, which meant they could be convinced. Kai Tanaka showed them a data chip — thirty seconds of the before — and watched their faces change. They stood aside. Some revolutions are just remembering, together."}, {'n': 4, 'title': 'The Remembering', 'text': "Kai Tanaka and the archivist Mina were in the tower when the door blew. The ex-enforcer held the stairs long enough. Long enough for what? For the footage to loop. For the memory to root. For the Overseer's lie to die on every screen at once.\n\nthe Overseer responded the only way the Overseer knew: force. The Patrol marched. The drones rose. And the people of the Sprawl — who had just remembered green, and laughter, and sky — stood in the streets and would not move.\n\nWhat happened in the next hour, historians argue about. What Kai Tanaka remembers: silence, then a sound like a held breath released, then the streets filling with people who had remembered they were people."}, {'n': 5, 'title': 'After the Static', 'text': "There were trials. the Overseer's people faced justice — real justice, not the Algorithm's kind, with evidence and mercy both. Some were guilty. Some were just afraid. Kai Tanaka learned the difference matters.\n\nAnd when the new council asked Kai Tanaka to lead, Kai Tanaka laughed and went back to the food lines. Leaders, Kai Tanaka had learned, are just people who show up. Kai Tanaka shows up.\n\nKai Tanaka kept the dead chip in a pocket. A reminder: that truth is a seed, that seeds die to grow, that one a data chip in the right hands at the right time is worth an army."}, {'n': 6, 'title': 'The Habit of Freedom', 'text': "Years later, the Sprawl has gardens on the roofs and children who've never seen a drone. They learn the story of a data chip in school, and Kai Tanaka always winces at the statue. 'I just carried it,' Kai Tanaka protests. Nobody believes that anymore.\n\nthe system fears the truth — Kai Tanaka thinks it every time, like a prayer, like a promise. Memory is resistance. Freedom is a habit. Practice daily.\n\nthe archivist Mina runs the network now — the real one, the open one, the one that belongs to everyone. The module is quieter. The neon is warmer. It turns out freedom has a sound, and it's laughter."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

